-- Row count, key sums and checksums: RAW.BRANCH
-- Expected values: data_sources/sample_db_extract/branch.csv
-- Canonicalisation: migration/validation/README.md
WITH canon AS (
    SELECT
        COALESCE(TO_VARCHAR(CAST(branch_id AS NUMBER(38, 0))), CHR(30)) AS c_branch_id,
        COALESCE(CAST(branch_name AS VARCHAR), CHR(30)) AS c_branch_name,
        COALESCE(CAST(branch_location AS VARCHAR), CHR(30)) AS c_branch_location,
        CAST(branch_id AS NUMBER(38, 4)) AS s_branch_id
    FROM raw.branch
),

hashed AS (
    SELECT
        s_branch_id,
        SHA2(CONCAT_WS(CHR(31), c_branch_id, c_branch_name, c_branch_location), 256) AS row_hash,
        SHA2(CONCAT_WS(CHR(31), c_branch_id), 256) AS key_hash
    FROM canon
)

SELECT
    COUNT(*) AS row_count,
    COALESCE(SUM(s_branch_id), 0) AS sum_branch_id,
    SHA2(COALESCE(LISTAGG(row_hash, ',') WITHIN GROUP (ORDER BY row_hash), ''), 256) AS checksum
FROM hashed;
